    }
    # for(i in seq_len(length(listSamples))) {
    #pos <- which(listSampleFile == listSamples[i])

    if(pRAIDS$verbose) { message("generateProfileGDS start ", " ", Sys.time()) }

    #    if(length(pos) == 1) {

