    } else if(pRAIDS$genoSource == "VCF") {
        # tmpProfile <- gsub(".vcf.gz", "",listMat[pos])
        matSample <- readSNVVCF(pRAIDS$profileFile,
                                profileName=pRAIDS$pedStudy$Name.ID[1], pRAIDS$offset)
    } else if(pRAIDS$genoSource == "bam"){
