                                verbose=pRAIDS$verbose)
        # listPos <- do.call(rbind, listPos)
        colnames(pRAIDS$listPos)[seq_len(2)] <- c("snp.chromosome", "snp.position")

    }
    # matAll <- merge(matSample[,c( "Chromosome", "Position",
